import React, { useState, useRef } from 'react';
import { CheckCircle2, Clock, Zap, AlertCircle, TrendingUp, Sun, Moon, BookOpen, Code2, LineChart, Smartphone, Star } from 'lucide-react';
import { DayData, Category } from '../types';

interface DashboardProps {
  dayData: DayData;
  toggleTask: (day: number, taskId: string) => void;
  skipTask: (day: number, taskId: string) => void;
  currentDay: number;
}

const CAT_META: Record<string, { color: string; bg: string; icon: React.FC<any>; cls: string }> = {
  'Morning Routine': { color: '#F59E0B', bg: 'rgba(245,158,11,0.1)',  icon: Sun,        cls: 'cat-morning'  },
  'English Learning': { color: '#22D3EE', bg: 'rgba(34,211,238,0.1)',  icon: BookOpen,   cls: 'cat-english'  },
  'Trading':          { color: '#10B981', bg: 'rgba(16,185,129,0.1)',  icon: LineChart,  cls: 'cat-trading'  },
  'Coding/DSA':       { color: '#8B5CF6', bg: 'rgba(139,92,246,0.1)', icon: Code2,      cls: 'cat-coding'   },
  'Flutter/React':    { color: '#4F8EF7', bg: 'rgba(79,142,247,0.1)', icon: Smartphone, cls: 'cat-flutter'  },
  'Night Review':     { color: '#6366F1', bg: 'rgba(99,102,241,0.1)', icon: Moon,       cls: 'cat-night'    },
};

const PHASES = [
  { range: [1,30],   label: 'Phase 1',  desc: 'Flutter Focus',        color: '#4F8EF7', gradient: 'linear-gradient(135deg,#4F8EF7,#22D3EE)' },
  { range: [31,60],  label: 'Phase 2',  desc: 'Flutter + React',      color: '#8B5CF6', gradient: 'linear-gradient(135deg,#6366F1,#8B5CF6)' },
  { range: [61,180], label: 'Phase 3',  desc: 'Full-Stack Mastery',   color: '#10B981', gradient: 'linear-gradient(135deg,#10B981,#22D3EE)' },
];

const SCHEDULE = [
  { time: '06:00',  label: 'Wake Up & Freshen',    cat: 'Morning',  color: '#F59E0B' },
  { time: '06:30',  label: 'Meditation & Gratitude', cat: 'Morning', color: '#F59E0B' },
  { time: '07:00',  label: 'English Practice',     cat: 'English',  color: '#22D3EE' },
  { time: '09:00',  label: 'Live Trading Session',  cat: 'Trading',  color: '#10B981' },
  { time: '19:00',  label: 'Trade Analysis',        cat: 'Trading',  color: '#10B981' },
  { time: '21:00',  label: 'DSA Practice',          cat: 'Coding',   color: '#8B5CF6' },
  { time: '21:30',  label: 'Flutter / React Build', cat: 'Dev',      color: '#4F8EF7' },
  { time: '23:30',  label: 'Night Review & Plan',   cat: 'Review',   color: '#6366F1' },
];

const QUOTES = [
  "Champions are made in the moments when they feel they can't go on.",
  "Discipline is the bridge between goals and accomplishment.",
  "Small daily improvements are the key to staggering long-term results.",
  "Success is the progressive realisation of a worthy ideal.",
  "Push yourself, because no one else is going to do it for you.",
  "Great things never come from comfort zones.",
  "The secret of getting ahead is getting started.",
];

const Dashboard: React.FC<DashboardProps> = ({ dayData, toggleTask, skipTask, currentDay }) => {
  const [popups, setPopups] = useState<{ id: string; pts: number; x: number; y: number }[]>([]);

  const phase = PHASES.find(p => currentDay >= p.range[0] && currentDay <= p.range[1]) || PHASES[2];
  const completed = dayData.tasks.filter(t => t.completed).length;
  const total = dayData.tasks.length;
  const pct = total ? Math.round((completed / total) * 100) : 0;
  const r = 52;
  const circ = 2 * Math.PI * r;
  const dash = circ * (1 - pct / 100);
  const quote = QUOTES[currentDay % QUOTES.length];
  const dateStr = new Date(dayData.date).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
  const overallProgress = Math.round((currentDay / 180) * 100);

  const handleToggle = (taskId: string, pts: number, wasDone: boolean, e: React.MouseEvent) => {
    toggleTask(currentDay, taskId);
    if (!wasDone) {
      const id = Math.random().toString(36).slice(2);
      setPopups(prev => [...prev, { id, pts, x: e.clientX, y: e.clientY }]);
      setTimeout(() => setPopups(prev => prev.filter(p => p.id !== id)), 1400);
    }
  };

  const categories = (Object.keys(CAT_META) as Category[]).filter(cat =>
    dayData.tasks.some(t => t.category === cat)
  );

  return (
    <div style={{ padding: '32px 36px', maxWidth: 1300, margin: '0 auto', position: 'relative' }}>

      {/* Score popups */}
      {popups.map(p => (
        <div key={p.id} className="score-popup" style={{ top: p.y - 10, left: p.x - 20 }}>
          +{p.pts}
        </div>
      ))}

      {/* ── Hero Header ── */}
      <div style={{ marginBottom: 32 }}>
        {/* Overall progress bar */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 24, padding: '14px 20px', background: 'rgba(255,255,255,0.03)', borderRadius: 16, border: '1px solid rgba(255,255,255,0.06)' }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: '#4F8EF7', flexShrink: 0, textTransform: 'uppercase', letterSpacing: '0.08em' }}>180-Day Journey</div>
          <div className="progress-bar-track" style={{ flex: 1, height: 8 }}>
            <div className="progress-bar-fill" style={{ width: `${overallProgress}%`, background: phase.gradient }} />
          </div>
          <div style={{ fontSize: 13, fontWeight: 800, color: '#F1F5F9', flexShrink: 0 }}>Day {currentDay} <span style={{ color: '#475569', fontWeight: 500 }}>/ 180</span></div>
          <div style={{ padding: '5px 14px', borderRadius: 99, background: `${phase.color}22`, border: `1px solid ${phase.color}44`, fontSize: 11, fontWeight: 700, color: phase.color, flexShrink: 0 }}>
            {phase.label}: {phase.desc}
          </div>
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 24, flexWrap: 'wrap' }}>
          {/* Left: Title */}
          <div>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8 }}>{dateStr}</div>
            <h1 style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 48, fontWeight: 700, color: '#F1F5F9', lineHeight: 1, letterSpacing: '-0.02em', marginBottom: 14 }}>
              Day <span style={{ background: phase.gradient, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>{currentDay}</span>
            </h1>
            <p style={{ fontSize: 15, color: '#64748B', lineHeight: 1.6, maxWidth: 420 }}>"{quote}"</p>
          </div>

          {/* Right: Stats row */}
          <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
            {/* Progress ring */}
            <div className="card-static" style={{ padding: '24px 28px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, minWidth: 160 }}>
              <div style={{ position: 'relative', width: 120, height: 120 }}>
                <svg width="120" height="120" className="progress-ring">
                  <circle cx="60" cy="60" r={r} fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="8" />
                  <circle
                    cx="60" cy="60" r={r} fill="none"
                    stroke="url(#ringGrad)" strokeWidth="8"
                    strokeLinecap="round"
                    strokeDasharray={circ}
                    strokeDashoffset={dash}
                    className="progress-ring-circle"
                  />
                  <defs>
                    <linearGradient id="ringGrad" x1="0%" y1="0%" x2="100%" y2="0%">
                      <stop offset="0%" stopColor="#4F8EF7" />
                      <stop offset="100%" stopColor="#8B5CF6" />
                    </linearGradient>
                  </defs>
                </svg>
                <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
                  <span style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 28, fontWeight: 700, color: '#F1F5F9', lineHeight: 1 }}>{pct}%</span>
                  <span style={{ fontSize: 10, color: '#475569', fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase', marginTop: 3 }}>Today</span>
                </div>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: '#F1F5F9' }}>{completed}/{total} Tasks</div>
                <div style={{ fontSize: 11, color: '#475569', marginTop: 2 }}>Completed today</div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ── Main Grid ── */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: 28 }}>

        {/* ── Left: Task Categories ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 28 }}>
          {categories.map(cat => {
            const meta = CAT_META[cat];
            const CatIcon = meta.icon;
            const tasks = dayData.tasks.filter(t => t.category === cat);
            const catDone = tasks.filter(t => t.completed).length;
            const catPct = Math.round((catDone / tasks.length) * 100);

            return (
              <section key={cat}>
                {/* Category Header */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16, padding: '10px 16px', borderRadius: 14, background: meta.bg, border: `1px solid ${meta.color}22` }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <div style={{ width: 32, height: 32, borderRadius: 10, background: `${meta.color}22`, border: `1px solid ${meta.color}44`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <CatIcon size={15} color={meta.color} />
                    </div>
                    <span style={{ fontSize: 14, fontWeight: 700, color: '#F1F5F9' }}>{cat}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <div style={{ width: 80, height: 5, borderRadius: 99, background: 'rgba(255,255,255,0.06)', overflow: 'hidden' }}>
                      <div style={{ width: `${catPct}%`, height: '100%', background: meta.color, borderRadius: 99, transition: 'width 0.6s ease', boxShadow: `0 0 6px ${meta.color}` }} />
                    </div>
                    <span style={{ fontSize: 12, fontWeight: 700, color: meta.color }}>{catDone}/{tasks.length}</span>
                  </div>
                </div>

                {/* Task Cards Grid */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 12 }}>
                  {tasks.map(task => (
                    <div
                      key={task.id}
                      className={`task-card ${task.completed ? 'completed' : ''} ${task.skipped ? 'skipped' : ''}`}
                      style={{ padding: '18px 20px' }}
                      onClick={e => handleToggle(task.id, task.points, task.completed, e)}
                    >
                      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 14 }}>
                        {/* Checkbox */}
                        <div className={`custom-checkbox ${task.completed ? 'checked' : ''}`} style={{ marginTop: 2 }}>
                          {task.completed && (
                            <svg width="13" height="10" viewBox="0 0 13 10" fill="none">
                              <path d="M1 5L5 9L12 1" stroke="#fff" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
                            </svg>
                          )}
                        </div>

                        {/* Content */}
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <p style={{ fontSize: 14, fontWeight: 600, color: task.completed ? '#64748B' : '#E2E8F0', textDecoration: task.completed ? 'line-through' : 'none', lineHeight: 1.4, marginBottom: 8 }}>
                            {task.title}
                          </p>
                          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 6 }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 5, color: '#475569', fontSize: 11, fontWeight: 600 }}>
                              <Clock size={11} />
                              <span>{task.time}</span>
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              {/* Status badge */}
                              {task.completed && <span className="badge badge-blue"><CheckCircle2 size={10} /> Done</span>}
                              {task.skipped && !task.completed && <span className="badge badge-orange">Skipped</span>}
                              {!task.completed && !task.skipped && <span className="badge" style={{ background: 'rgba(255,255,255,0.04)', color: '#475569', border: '1px solid rgba(255,255,255,0.06)' }}>Pending</span>}

                              {/* Points */}
                              <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, fontWeight: 700, color: task.completed ? meta.color : '#475569' }}>
                                <Zap size={10} fill={task.completed ? meta.color : 'none'} color={task.completed ? meta.color : '#475569'} />
                                +{task.points}
                              </span>

                              {/* Skip btn */}
                              {!task.completed && (
                                <button
                                  onClick={e => { e.stopPropagation(); skipTask(currentDay, task.id); }}
                                  style={{ fontSize: 10, fontWeight: 700, color: task.skipped ? '#F59E0B' : '#475569', background: 'transparent', border: 'none', cursor: 'pointer', padding: '2px 6px', borderRadius: 6, transition: 'color 0.2s' }}
                                >
                                  {task.skipped ? '↩ Undo' : 'Skip'}
                                </button>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </section>
            );
          })}
        </div>

        {/* ── Right Sidebar ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

          {/* Quick stats */}
          <div className="card-static" style={{ padding: '20px 22px' }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 16 }}>Today's Stats</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              {[
                { label: 'Completed', value: completed, color: '#10B981' },
                { label: 'Pending',   value: total - completed - dayData.tasks.filter(t => t.skipped).length, color: '#64748B' },
                { label: 'Skipped',   value: dayData.tasks.filter(t => t.skipped).length, color: '#F59E0B' },
                { label: 'Points',    value: dayData.tasks.filter(t=>t.completed).reduce((s,t)=>s+t.points,0), color: '#4F8EF7' },
              ].map(stat => (
                <div key={stat.label} style={{ padding: '14px 16px', background: 'rgba(255,255,255,0.03)', borderRadius: 12, border: '1px solid rgba(255,255,255,0.05)' }}>
                  <div style={{ fontSize: 22, fontWeight: 800, color: stat.color, fontFamily: "'Space Grotesk',sans-serif", lineHeight: 1 }}>{stat.value}</div>
                  <div style={{ fontSize: 11, color: '#475569', fontWeight: 600, marginTop: 4 }}>{stat.label}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Schedule Timeline */}
          <div className="card-static" style={{ padding: '20px 22px' }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 20 }}>Daily Timeline</div>
            <div style={{ position: 'relative', paddingLeft: 24 }}>
              <div className="timeline-line" />
              <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
                {SCHEDULE.map((s, i) => {
                  const now = new Date();
                  const [h, m] = s.time.split(':').map(Number);
                  const slotDate = new Date(); slotDate.setHours(h, m, 0, 0);
                  const isPast = now > slotDate;
                  const isCurrent = i < SCHEDULE.length - 1 && (() => {
                    const [nh, nm] = SCHEDULE[i+1].time.split(':').map(Number);
                    const next = new Date(); next.setHours(nh, nm, 0, 0);
                    return now >= slotDate && now < next;
                  })();

                  return (
                    <div key={i} style={{ position: 'relative', paddingLeft: 16 }}>
                      <div style={{ position: 'absolute', left: -28, top: 6, width: 10, height: 10, borderRadius: '50%', background: isCurrent ? s.color : isPast ? '#1E293B' : '#0D1120', border: `2px solid ${isCurrent ? s.color : isPast ? '#334155' : '#1E293B'}`, boxShadow: isCurrent ? `0 0 12px ${s.color}` : 'none', transition: 'all 0.3s' }} />
                      <div style={{ fontSize: 10, fontWeight: 700, color: isCurrent ? s.color : '#334155', letterSpacing: '0.1em', marginBottom: 2 }}>{s.time.replace(':', ':')} {parseInt(s.time) >= 12 ? 'PM' : 'AM'}</div>
                      <div style={{ fontSize: 13, fontWeight: 600, color: isCurrent ? '#F1F5F9' : isPast ? '#475569' : '#94A3B8' }}>{s.label}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Tip card */}
          <div style={{ padding: '20px 22px', borderRadius: 20, background: 'linear-gradient(135deg,rgba(79,142,247,0.12),rgba(139,92,246,0.08))', border: '1px solid rgba(79,142,247,0.2)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
              <AlertCircle size={16} color="#4F8EF7" />
              <span style={{ fontSize: 12, fontWeight: 700, color: '#4F8EF7', letterSpacing: '0.08em', textTransform: 'uppercase' }}>Penalty Reminder</span>
            </div>
            <p style={{ fontSize: 13, color: '#94A3B8', lineHeight: 1.6 }}>
              Missing <strong style={{ color: '#F87171' }}>Trading</strong> or <strong style={{ color: '#F87171' }}>Dev</strong> sessions without skipping costs <strong style={{ color: '#F87171' }}>-10 pts</strong> each. Always use Skip if unavailable.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
